//! Std-only smoke run of the `unitree_webrtc` libFuzzer target
//! (`fuzz/fuzz_targets/`): the same harness (`fuzz/harness/unitree_webrtc.rs`,
//! included by path) driven by the deterministic mutator in
//! `fuzz/harness/smoke.rs` over the committed seed corpus. The seeds are
//! (re)generated by `regenerate_seeds` (run with `--ignored`).

#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;
#[path = "../../../fuzz/harness/unitree_webrtc.rs"]
mod unitree_webrtc;

const DIR: &str = env!("CARGO_MANIFEST_DIR");

fn rec(out: &mut Vec<u8>, flags: u8, b: &[u8]) {
    out.extend_from_slice(&(b.len() as u16).to_be_bytes());
    out.push(flags);
    out.extend_from_slice(b);
}

fn stun_request() -> Vec<u8> {
    let mut m = vec![0x00, 0x01, 0x00, 0x08, 0x21, 0x12, 0xA4, 0x42];
    m.extend_from_slice(&[9; 12]);
    m.extend_from_slice(&[0x00, 0x06, 0x00, 0x03, b'a', b':', b'b', 0]);
    m
}

fn dtls(kind: u8, ty: u8, epoch: u8) -> Vec<u8> {
    vec![
        ty, 0xFE, 0xFD, 0, epoch, 0, 0, 0, 0, 0, 1, 0, 4, kind, 0, 0, 0,
    ]
}

fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    let (pwd, token) = unitree_webrtc::secrets();
    let sdp = format!(
        "v=0\r\nm=video 9 UDP/TLS/RTP/SAVPF 96\r\na=ice-ufrag:AbCd\r\na=ice-pwd:{pwd}\r\n\
         a=fingerprint:sha-256 01:02\r\na=candidate:1 1 udp 1 192.168.123.20 5 typ host\r\n"
    );
    let body = serde_json::json!({"sdp": sdp, "type": "offer", "token": token}).to_string();
    let offer = format!(
        "POST /offer HTTP/1.1\r\nContent-Length: {}\r\n\r\n{body}",
        body.len()
    );
    let mut session = vec![1u8];
    rec(&mut session, 0x01, offer.as_bytes());
    rec(
        &mut session,
        0x03,
        b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n",
    );
    rec(&mut session, 0x00, &stun_request());
    rec(&mut session, 0x00, &dtls(1, 22, 0));
    rec(&mut session, 0x02, &dtls(2, 22, 0));
    rec(&mut session, 0x02, &dtls(0, 23, 1));
    let mut intruder = vec![3u8];
    rec(
        &mut intruder,
        0x51,
        b"POST /con_notify HTTP/1.1\r\nContent-Length: 0\r\n\r\n",
    );
    rec(
        &mut intruder,
        0x51,
        b"POST /con_ing_abc HTTP/1.1\r\nContent-Length: 4\r\n\r\nabcd",
    );
    rec(&mut intruder, 0x50, &stun_request());
    rec(
        &mut intruder,
        0x52,
        &[0x80, 96, 0, 1, 0, 0, 0, 1, 0, 0, 0, 9],
    );
    rec(&mut intruder, 0x52, &[0x40, 0, 0, 4, 1, 2, 3, 4]);
    vec![
        ("seed-webrtc-session.bin", session),
        ("seed-webrtc-intruder.bin", intruder),
    ]
}

#[test]
#[ignore = "regenerates fuzz/corpus/unitree_webrtc"]
fn regenerate_seeds() {
    let dir = smoke::corpus_dir(DIR, "unitree_webrtc");
    std::fs::create_dir_all(&dir).unwrap();
    for (name, bytes) in seeds() {
        std::fs::write(dir.join(name), bytes).unwrap();
    }
}

#[test]
fn committed_seeds_match_the_generator() {
    let committed = smoke::corpus(DIR, "unitree_webrtc");
    for (_, s) in seeds() {
        assert!(
            committed.contains(&s),
            "a seed changed: run regenerate_seeds"
        );
    }
}

#[test]
fn unitree_webrtc_smoke() {
    let mut seeds: Vec<Vec<u8>> = smoke::corpus(DIR, "unitree_webrtc");
    seeds.extend(self::seeds().into_iter().map(|(_, s)| s));
    smoke::run("unitree_webrtc", &seeds, 0x3eb7_0c00, &unitree_webrtc::run);
}
